// Data flows through gzip (if compress) then encryption (if encryptor is not nil) before reaching the pipe.
func storageReadWriteCloser(count int, compress bool, encryptor *encryption.Encryptor) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()

		prs = append(prs, pr)

		var w io.Writer = pw
		var ew io.WriteCloser

		if encryptor != nil {
			ew = encryptor.EncryptWriter(w)
			w = ew
		}

		if compress {
			gw := gzip.NewWriter(w)
			w = gw
			pcs = append(pcs, gw)
		}

		pws = append(pws, w)

		// Closers must be ordered from the outermost writer to the innermost one,
		// so that gzip flushes into the encryptor before the encryptor writes its trailer.
		if ew != nil {
